  str_n_plus_six_mission_desc_1 = "Incluso si estás solo, asegúrate de hacer los preparativos necesarios para el próximo festival.",
  str_n_plus_six_mission_desc_2 = "A medida que se acerca Windelion, parece que alguien te ha preparado una sorpresa.",
  str_n_plus_six_mission_desc_3 = "¡Es hora de entrar a Eraveil y encontrar la publicación!",
  str_n_plus_six_mission_desc_4 = "Los eclipsites yacían ocultos en todos los rincones de Eraveil. ¡Encuéntralos y deshazte de ellos!",
  str_n_plus_six_mission_desc_5 = "Mientras usas tu habilidad psíquica, ocasionalmente detecta otras auras desconocidas ...",
  str_n_plus_six_mission_desc_6 = "Tu misión de erradicar los Eclipsites de Eraveil avanza sin problemas, pero cuanto más derrotes, más recordarás el pasado de Eraveil.",
  str_n_plus_six_mission_desc_7 = "Se está produciendo un cambio en el cielo sobre Eraveil ...",
  str_n_plus_six_mission_desc_8 = "Cuida tus pasos y ten cuidado con las trampas de Eclipsite ...",
  str_n_plus_six_mission_desc_9 = "Las familias Pirro y Gautier fueron expulsadas de Lumopolis por incitar a la rebelión. Por eso Mirren Gautier te desprecia a ti y a tus aliados.",
  str_n_plus_six_mission_desc_10 = "Paloma también esconde un pasado desconocido ...",
  str_n_plus_six_mission_desc_11 = "Mirren huyó de la escena, pero aún existe la posibilidad de que puedas alcanzarlo.",
  str_n_plus_six_mission_desc_12 = "¿Paloma es una enemiga o una amiga?",
  str_n_plus_six_mission_desc_13 = "¡Debemos acabar con Mirren! ¡No podemos permitir que su plan tenga éxito!",
  str_n_plus_six_mission_desc_long_1 = "Vice te contacta. Parece haber estado muy ocupada desde que regresó a Illumina. Te sientes un poco solo, pero tratas de mantener el ánimo en alto y prepararte para el festival Windelion de Celestitas.",
  str_n_plus_six_mission_desc_long_2 = "Vice y Carleen traen una gran delegación a Eraveil. Algunos de ellos quieren ayudar a reconstruir el Puesto de Eraveil, mientras que otros desean ayudar a acabar con los Eclipsites. De repente, tu vida se ha vuelto bastante emocionante.",
  str_n_plus_six_mission_desc_long_3 = "Después de pasar por un cementerio familiar y llegar al puesto de la Torre Blanca, Naroxel se hace cargo del esfuerzo posterior a la reparación en nombre de Unión de Mensajería.",
  str_n_plus_six_mission_desc_long_4 = "Los Eclipsites parecen estar planeando algo. Frente al engaño y el peligro, su capacidad psíquica se convierte una vez más en su activo más valioso.",
  str_n_plus_six_mission_desc_long_5 = "Originalmente tenías la intención de usar tu habilidad psíquica para localizar los Eclipsites escondidos en Eraveil, pero inesperadamente sentiste un extraño y poderoso Aurorian.",
  str_n_plus_six_mission_desc_long_6 = "El misterioso Aurorian parece estar buscando algo por todas partes. De pie en el desolado Eraveil, no puede evitar recordar la guerra que una vez tuvo lugar aquí.",
  str_n_plus_six_mission_desc_long_7 = "El Eclipse aparece de repente y un fenómeno anormal parece estar afectando su capacidad psíquica. Después de calmarse, decide reunirse con Unión de Mensajería.",
  str_n_plus_six_mission_desc_long_8 = "La Eclipsite que se esconde en las sombras finalmente aparece ante ti. No se trata de una Eclipsite corriente, sino del traidor que Pittman ha intentado localizar—Mirren Gautier.",
  str_n_plus_six_mission_desc_long_9 = "Mirren tiene un amargo rencor contra ti y tus aliados tras de ser desterrado de Lumopolis. Justo cuando la crisis golpea, aparece la poderosa Aurorian, Paloma. Sin embargo, toda su familia, los Pyrrhuses, también fueron desterrados de Lumopolis debido a las acusaciones de rebelión.",
  str_n_plus_six_mission_desc_long_10 = "Ante la inminente derrota, Mirren eligió huir sin dudarlo ni un momento. De pie ante su antigua enemiga de Lumopolis, Paloma recuerda su trágico pasado y cree firmemente que Mirren debe saber la verdad detrás del incidente.",
  str_n_plus_six_mission_desc_long_11 = "Paloma usa su poder psíquico para encontrar a Mirren, sin embargo, ella elige perseguirlo sola.",
  str_n_plus_six_mission_desc_long_12 = "Aunque Paloma proviene de la familia Pyrrhus, acusada de incitar a una rebelión, esperas sinceramente que no sea en realidad un enemigo.",
  str_n_plus_six_mission_desc_long_13 = "Ante el nuevo poder de Mirren, Paloma libra una batalla perdida. Afortunadamente, llegas a tiempo para derrotar juntos a Mirren. Aunque el astuto Mirren logra escapar, logras frustrar su plan.",
  str_n_plus_six_mission_sidename_1 = "Hora de Actuar",
