  str_n_plus_six_mission_sidename_19 = "Danza de las Luciérnagas",
  str_n_plus_six_mission_sidename_20 = "Miedo a las Alturas",
  str_n_plus_six_mission_sidename_21 = "Pecera",
  str_n_plus_six_mission_sidename_22 = "Percha de gato",
  str_n_plus_six_mission_sidename_23 = "¡Misión Cumplida!",
  str_n_plus_six_mission_side_1 = "¡La Unión de Mensajería está lista para la acción y aún queda mucho trabajo por hacer para que la publicación vuelva a funcionar!",
  str_n_plus_six_mission_side_2 = "Aunque ahora están impecables, los estantes del mostrador de recepción permanecen vacíos.",
  str_n_plus_six_mission_side_3 = "¿Todavía hay dinero en la caja? ¡Ni se te ocurra pasarla!",
